// buildSeq namespaces rewriters per build so an old hop keeps resolving its own
// targets while a new build is being prepared. x's rewriter registry resolves
// names lazily, so reusing a name would mutate the live data plane before the
// hop swap.
var buildSeq atomic.Uint64

func nextBuildGeneration() string {
	return strconv.FormatUint(buildSeq.Add(1), 10)
}

// buildHopGroup compiles the configured routes into a hop group and emits one
// entry per entrypoint and inbound protocol group, in declaration order,
// followed by the entrypoint's fallback e

ntry. The FIFO group selector then
// makes entrypoint order the single precedence rule. The returned names are the
// rewriters registered for this build; the caller owns their lifecycle.
func buildHopGroup(cfg *gwconfig.Config, build string, log logger.Logger, facts *stats.Facts, captureMgr *capture.Manager) (hop.Hop, []string, error) {
	if err := registerHeaderRewriter(); err != nil {
		return nil, nil, err
	}

	routes := make(map[string]gwconfig.Route, len(cfg.Routes))
	for _, r := range cfg.Routes {
		routes[r.Name] = r
	}
	routePlans := make(map[string]*routePlan, len(cfg.Routes))
	var rewriters []string
	entries := make([]*xhop.HopEntry, 0, len(cfg.Entrypoints)*(len(inboundGroups)+1))

for _, e := range cfg.Entrypoints {
	r, ok := routes[e.Route]
	if !ok {
		return nil, rewriters, fmt.Errorf("entrypoint %q: unknown route %q", e.Name, e.Route)
	}
	plan, ok := routePlans[r.Name]
	if !ok {
		var err error
		plan, err = buildRoutePlan(cfg, build, r, log, facts, captureMgr)
		if plan != nil {
			rewriters = append(rewriters, plan.rewriters...)
		}
		if err != nil {
			return nil, rewriters, fmt.Errorf("route %q: %w", r.Name, err)
		}
		routePlans[r.Name] = plan
	}

	for _, group := range inboundGroups {
		h, ok := plan.hops[group.api]
		if !ok {
			continue
		}
		m, err := buildProtocolMatcher(e.Match, group.pathPattern)
		if err != nil {
			return nil

, rewriters, fmt.Errorf("entrypoint %q: %w", e.Name, err)
			}
			entries = append(entries, xhop.NewHopEntry(h, m, nil))
		}

		m, err := buildEntrypointMatcher(e.Match)
		if err != nil {
			return nil, rewriters, fmt.Errorf("entrypoint %q: %w", e.Name, err)
		}
		entries = append(entries, xhop.NewHopEntry(plan.hops[""], m, nil))
	}
	return xhop.NewHopGroup(
		xhop.WithEntriesOption(entries...),
		xhop.WithGroupSelectorOption(xs.NewSelector(xs.FIFOStrategy[hop.Hop]())),
		xhop.WithGroupLoggerOption(log.WithFields(map[string]any{
			"kind": "hopGroup",
		})),
	), rewriters, nil
}

// routePlan holds the compiled hops for one route: the fallback variant under
// the empty API key and one varia

nt per inbound protocol that changes at least
// one node's target API. rewriters are the names registered by this plan.
type routePlan struct {
	hops      map[provider.API]hop.Hop
	rewriters []string
}

// nodePlan is one enabled node and its compiled target plan.
type nodePlan struct {
	provider gwconfig.Provider
	node     gwconfig.Node
	targets  nodeTargets
}

func buildRoutePlan(cfg *gwconfig.Config, build string, r gwconfig.Route, log logger.Logger, facts *stats.Facts, captureMgr *capture.Manager) (*routePlan, error) {
	providers := make(map[string]gwconfig.Provider, len(cfg.Providers))
	for _, p := range cfg.Providers {
		providers[p.Name] = p
	}
	bindings := make(map[string]gwconfig.N

ode, len(cfg.Nodes))
	for _, n := range cfg.Nodes {
		bindings[n.Name] = n
	}

	var plans []nodePlan
	for _, ref := range r.Nodes {
		n, ok := bindings[ref]
		if !ok {
			return nil, fmt.Errorf("unknown node %q", ref)
		}
		if !n.EnabledValue() {
			continue
		}
		p, ok := providers[n.Provider]
		if !ok {
			return nil, fmt.Errorf("node %q: unknown provider %q", n.Name, n.Provider)
		}
		if !p.EnabledValue() {
			continue
		}
		targets, err := compileNodeTargets(p, n)
		if err != nil {
			if errors.Is(err, errModelDisabled) {
				log.Warnf("route %s node %s: %v", r.Name, n.Name, err)
				continue
			}
			return nil, fmt.Errorf("node %q: %w", n.Name, err)
		}
		plans = append(plans, nodePlan{

provider: p, node: n, targets: targets})
	}

	plan := &routePlan{hops: make(map[provider.API]hop.Hop, len(inboundGroups)+1)}
	def, err := buildVariantHop(r, build, "", plans, log, facts, captureMgr, &plan.rewriters)
	if err != nil {
		return plan, err
	}
	plan.hops[""] = def

	needed := make(map[provider.API]bool)
	for _, np := range plans {
		for api := range np.targets.variants {
			needed[api] = true
		}
	}
	for _, group := range inboundGroups {
		if !needed[group.api] {
			continue
		}
		h, err := buildVariantHop(r, build, group.api, plans, log, facts, captureMgr, &plan.rewriters)
		if err != nil {
			return plan, err
		}
		plan.hops[group.api] = h
	}
	return plan, nil
}

// buildVariant

Hop compiles one route variant. inbound is empty for the fallback
// variant; otherwise every node uses its per-protocol target when it has one.
func buildVariantHop(r gwconfig.Route, build string, inbound provider.API, plans []nodePlan, log logger.Logger, facts *stats.Facts, captureMgr *capture.Manager, names *[]string) (hop.Hop, error) {
	variant := variantKey(inbound)
	var nodes []*xconfig.NodeConfig
	for _, np := range plans {
		target := np.targets.defaultTarget
		if inbound != "" {
			if t, ok := np.targets.variants[inbound]; ok {
				target = t
			}
		}
		name := buildRewriterName(build, r.Name, variant, np.node.Name)
		if err := registerRewriter(name, np.provider, np.node, target, r.

Name, facts, captureMgr, log); err != nil {
			return nil, err
		}
		*names = append(*names, name)
		ns, err := buildNodes(np.provider, np.node, r.Name, target, name)
		if err != nil {
			return nil, fmt.Errorf("node %q: %w", np.node.Name, err)
		}
		nodes = append(nodes, ns...)
	}

	strategy := r.Strategy
	if strategy == "" {
		strategy = "round"
	}
	return hop_parser.ParseHop(&xconfig.HopConfig{
		Name: "route/" + r.Name + "/" + variant,
		Selector: &xconfig.SelectorConfig{
			Strategy: strategy,
		},
		Nodes: nodes,
	}, log)
}

func buildNodes(p gwconfig.Provider, n gwconfig.Node, route string, target upstreamTarget, rewriter string) ([]*xconfig.NodeConfig, error) {
	auth := target.auth

u, err := url.Parse(strings.TrimSpace(target.baseURL))
if err != nil || u.Host == "" {
	return nil, fmt.Errorf("invalid base URL %q", target.baseURL)
}

secure := u.Scheme == "https"
port := u.Port()
if port == "" {
	if secure {
		port = "443"
	} else {
		port = "80"
	}
}
addr := net.JoinHostPort(u.Hostname(), port)

var tlsCfg *xconfig.TLSNodeConfig
if secure {
	serverName := p.TLS.ServerName
	if serverName == "" {
		serverName = u.Hostname()
	}
	verify := true
	if p.TLS.Secure != nil {
		verify = *p.TLS.Secure
	}
	tlsCfg = &xconfig.TLSNodeConfig{ServerName: serverName, Secure: verify}
}

rewrites := upstreamRewrites(target.baseURL, target.api, target.targetModel)

keys := p.Keys
if len(keys) == 0 {
	keys = []string{""}
}

nodes := make([]*xconfig.NodeConfig, 0, len(keys))
for i, key := range keys {
	headers := make(map[string]string, len(auth.Extra)+5)
	// The gateway owns upstream authentication. Inbound credentials, such
	// as the Authorization header Claude Code sends or an SDK's x-api-key,
	// must never be forwarded: some upstreams (DeepSeek's Anthropic
	// endpoint, for example) prefer Authorization over x-api-key, so a
	// leaked client token would turn the valid provider key into a 401.
	// Empty values delete the header in x's HTTP forwarder.
	for _, h := range []string{"Authorization", "x-api-key", "x-goog-api-key", "api-key

"} {
			headers[h] = ""
		}
		if key != "" {
			if auth.Header != "" {
				headers[auth.Header] = auth.Prefix + key
			}
			for _, kh := range auth.KeyHeaders {
				if kh.Header == "" {
					continue
				}
				headers[kh.Header] = kh.Prefix + key
			}
		}
		// Extra is the user's final override: apply it after every
		// key-derived header so an explicit value always wins.
		for k, v := range auth.Extra {
			headers[k] = v
		}
		// The x forwarder cannot rewrite compressed SSE. Drop the client's
		// Accept-Encoding so net/http negotiates gzip itself and transparently
		// decompresses the upstream body before the body rewriter sees it.
		// This is a transport concern, not an auth override,

 so it must win
		// over auth.Extra as well.
		headers["Accept-Encoding"] = ""

		name := fmt.Sprintf("%s/%s/%s", route, p.Name, n.Name)
		if len(keys) > 1 {
			name = fmt.Sprintf("%s/%d", name, i)
		}

		bodyRewrites := []xconfig.HTTPBodyRewriteConfig{{
			Rewriter: rewriter,
			Type:     "*",
		}}

		var metadata map[string]any
		if n.Backup {
			metadata = map[string]any{"backup": true}
		}
		if n.Weight > 0 {
			if metadata == nil {
				metadata = make(map[string]any)
			}
			metadata["weight"] = n.Weight
		}

		nodeCfg := &xconfig.NodeConfig{
			Name:     name,
			Addr:     addr,
			TLS:      tlsCfg,
			Metadata: metadata,
			HTTP: &xconfig.HTTPNodeConfig{
				Host:                u.Ho

st,
				RequestHeader:       headers,
				RewriteURL:          rewrites,
				RewriteRequestBody:  bodyRewrites,
				RewriteResponseBody: bodyRewrites,
				RewriteResponseHeader: []xconfig.HTTPHeaderRewriteConfig{{
					Rewriter: gwrewriter.RequestIDRewriterName,
				}},
				FailCodes: "429,5xx",
			},
		}
		nodes = append(nodes, nodeCfg)
	}
	return nodes, nil
}

// buildEntrypointMatcher compiles one entrypoint's model globs into a single
// anchored body-model matcher. The entrypoint order in the hop group, not the
// order inside this list, decides precedence.
func buildEntrypointMatcher(match []string) (corerouting.Matcher, error) {
	pattern, catchAll, err := modelGlobPattern(match)
	if e

rr != nil {
		return nil, err
	}
	if catchAll {
		return nil, nil
	}
	return xrouting.NewMatcher(fmt.Sprintf("BodyJSON(%q, %q)", "model", pattern))
}

// globToRegexp converts a small glob (* only) to an anchored Go regexp.
func globToRegexp(glob string) string {
	parts := strings.Split(glob, "*")
	var b strings.Builder
	b.WriteString("^")
	for i, part := range parts {
		if i > 0 {
			b.WriteString(".*")
		}
		b.WriteString(regexp.QuoteMeta(part))
	}
	b.WriteString("$")
	return b.String()
}

// variantKey names one route variant for rewriter keys and hop names.
func variantKey(api provider.API) string {
	if api == "" {
		return "default"
	}
	return string(api)
}

// rewriterName returns the

registry key for a route-scoped node engine. The
// same node can select different target APIs in different routes and protocol
// variants, so engines cannot be shared. Route and node names forbid '/', and
// the variant is one of a fixed set, so the key cannot collide.
func rewriterName(route, variant, node string) string {
	return "r/" + route + "/" + variant + "/" + node
}

func registerHeaderRewriter() error {
	name := gwrewriter.RequestIDRewriterName
	registry.RewriterRegistry().Unregister(name)
	if err := registry.RewriterRegistry().Register(name, &gwrewriter.HeaderRewriter{}); err != nil {
		return fmt.Errorf("register header rewriter %s: %w", name, err)
	}
	return nil
}

// buildRew

riterName namespaces a rewriter by build generation. x resolves
// rewriter names lazily, so a stable name would let a new build mutate the old
// hop before the swap.
func buildRewriterName(build, route, variant, node string) string {
	return "b/" + build + "/" + rewriterName(route, variant, node)
}

// unregisterRewriters removes names registered by one build or retained for the
// drain window of a previous build.
func unregisterRewriters(names []string) {
	for _, name := range names {
		registry.RewriterRegistry().Unregister(name)
	}
}

// registerRewriter installs the in-process body rewriter for one route variant
// and node. It must run before ParseHop because node parsing resolves re

writers
// from the registry.
func registerRewriter(name string, p gwconfig.Provider, n gwconfig.Node, target upstreamTarget, route string, facts *stats.Facts, captureMgr *capture.Manager, log logger.Logger) error {
	registry.RewriterRegistry().Unregister(name)
	if err := registry.RewriterRegistry().Register(name, gwrewriter.New(newNodeEngine(target), gwrewriter.Options{
		Provider:    p.Name,
		Protocol:    string(target.api),
		Route:       route,
		Node:        n.Name,
		TargetModel: target.targetModel,
		Sink:        facts,
		Capture:     captureMgr,
		Logger:      log,
	})); err != nil {
		return fmt.Errorf("register rewriter %s: %w", name, err)
	}
	return nil
}

func newNodeEngine(targ

et upstreamTarget) *engine.Engine {
	targetModel := target.targetModel
	engineProto := engineProtocol(target.api)
	return engine.New(engine.Options{
		Model:     targetModel,
		MaxTokens: 8192,
		Cache:     "memory",
		ResolveModel: func(string, string) (string, string, string) {
			return targetModel, engineProto, ""
		},
	})
}

package gateway

import (
	"context"
	"errors"
	"fmt"
	"net/url"
	"strings"

	xconfig "github.com/go-gost/x/config"

	gwconfig "github.com/go-gost/llm-gw/internal/config"
	"github.com/go-gost/llm-gw/internal/provider"
)

// errModelDisabled marks a node whose compiled target model is locally disabled
// by its provider. Routes skip such nodes instead of failing the whole
// configuration, matching the existing disabled-provider and disabled-node
// behavior.
var errModelDisabled = errors.New("target model is disabled")

// upstreamTarget is the result of compiling one route against one provider: a
// single base URL, wire API and provider model. A route has exactly one
// target, so its URL

rewrites stay static.
type upstreamTarget struct {
	baseURL     string
	api         provider.API
	targetModel string
	auth        gwconfig.Auth
}

// nodeTargets is the compiled API plan for one node. defaultTarget is used for
// the fallback group and for every inbound group that has no distinct variant.
type nodeTargets struct {
	defaultTarget upstreamTarget
	variants      map[provider.API]upstreamTarget
}

// compileNodeTargets resolves the default target and the per-protocol variants
// for one node. A pinned API bypasses default selection entirely; otherwise the
// default follows the model's static classification and each protocol variant
// is used only when the provider can serve tha

t protocol for this model.
func compileNodeTargets(p gwconfig.Provider, n gwconfig.Node) (nodeTargets, error) {
	targetModel := strings.TrimSpace(n.Model)
	if targetModel == "" {
		return nodeTargets{}, fmt.Errorf("node %q: model is required", n.Name)
	}
	prov, err := provider.New(p)
	if err != nil {
		return nodeTargets{}, err
	}
	if p.ModelDisabled(targetModel) {
		return nodeTargets{}, fmt.Errorf("%w: %s", errModelDisabled, targetModel)
	}

	if pinned := strings.TrimSpace(n.API); pinned != "" {
		target, err := compileTarget(prov, p, n, provider.API(pinned))
		if err != nil {
			return nodeTargets{}, err
		}
		return nodeTargets{defaultTarget: target}, nil
	}

	api, model, err := selectAP

I(context.Background(), prov, targetModel)
	if err != nil {
		return nodeTargets{}, err
	}
	def, err := compileTarget(prov, p, n, api)
	if err != nil {
		return nodeTargets{}, err
	}
	out := nodeTargets{defaultTarget: def}
	for _, inbound := range []provider.API{provider.Chat, provider.Responses, provider.Anthropic, provider.Gemini} {
		if inbound == api {
			continue
		}
		if _, ok := prov.BaseURL(inbound); !ok {
			continue
		}
		if len(model.APIs) > 0 && !containsAPI(model.APIs, inbound) {
			continue
		}
		target, err := compileTarget(prov, p, n, inbound)
		if err != nil {
			return nodeTargets{}, err
		}
		if out.variants == nil {
			out.variants = make(map[provider.API]upstreamTarget)

		}
		out.variants[inbound] = target
	}
	return out, nil
}

// compileTarget builds one concrete upstream target for api.
func compileTarget(prov provider.Provider, _ gwconfig.Provider, n gwconfig.Node, api provider.API) (upstreamTarget, error) {
	baseURL, ok := prov.BaseURL(api)
	if !ok {
		return upstreamTarget{}, fmt.Errorf("node %q: API %q has no base URL", n.Name, api)
	}
	return upstreamTarget{
		baseURL:     baseURL,
		api:         api,
		targetModel: strings.TrimSpace(n.Model),
		auth:        prov.Auth(api),
	}, nil
}

func containsAPI(apis []provider.API, api provider.API) bool {
	for _, candidate := range apis {
		if candidate == api {
			return true
		}
	}
	return false
}

// sele

ctAPI resolves modelID and picks the first API the provider both
// advertises for that model and has a base URL for. Models without a static
// API classification fall back to the canonical provider order, which keeps
// unknown or newly listed models routable.
func selectAPI(_ context.Context, p provider.Provider, modelID string) (provider.API, provider.Model, error) {
	modelID = strings.TrimSpace(modelID)
	model, _ := p.Resolve(modelID)

	if len(model.APIs) > 0 {
		for _, api := range model.APIs {
			if _, ok := p.BaseURL(api); ok {
				return api, model, nil
			}
		}
		return "", model, fmt.Errorf("model %q: APIs %s have no base URL", modelID, joinAPIs(model.APIs))
	}

	for _, api := ran

ge []provider.API{provider.Chat, provider.Responses, provider.Anthropic, provider.Gemini} {
		if _, ok := p.BaseURL(api); ok {
			return api, model, nil
		}
	}
	return "", model, fmt.Errorf("model %q: no API base URL configured", modelID)
}

func joinAPIs(apis []provider.API) string {
	parts := make([]string, 0, len(apis))
	for _, api := range apis {
		parts = append(parts, string(api))
	}
	return strings.Join(parts, ", ")
}

// engineProtocol maps an upstream API to the llm-api-converter protocol name.
func engineProtocol(api provider.API) string {
	if api == provider.Chat {
		return "openai"
	}
	return string(api)
}

// upstreamRewrites maps every supported inbound path to the canonical pa

th of
// the selected API. Query strings are left untouched by the rewrite engine.
func upstreamRewrites(baseURL string, api provider.API, targetModel string) []xconfig.HTTPURLRewriteConfig {
	u, err := url.Parse(strings.TrimSpace(baseURL))
	if err != nil {
		return nil
	}

	basePath := strings.TrimSuffix(u.Path, "/")
	sources := []string{
		`^/v1/chat/completions$`,
		`^/v1/responses$`,
		`^/v1/messages$`,
		`^/v1/messages/count_tokens$`,
		`^/v1beta/models/[^/]+:generateContent$`,
		`^/v1beta/models/[^/]+:streamGenerateContent$`,
	}

	out := make([]xconfig.HTTPURLRewriteConfig, 0, len(sources))
	for _, source := range sources {
		var replacement string
		switch {
		case strings.HasSuffix(s

ource, `count_tokens$`):
			// Token counting is an Anthropic-only path; other targets keep the
			// historical pass-through behavior.
			if api == provider.Anthropic {
				replacement = anthropicPath(basePath, "/v1/messages/count_tokens")
			}
		case strings.HasSuffix(source, `:streamGenerateContent$`) && api == provider.Gemini:
			replacement = geminiPath(basePath, targetModel, true)
		default:
			replacement = canonicalPath(basePath, api, targetModel)
		}
		if replacement == "" {
			continue
		}
		out = append(out, xconfig.HTTPURLRewriteConfig{
			Match:       source,
			Replacement: strings.ReplaceAll(replacement, "$", "$$"),
		})
	}
	return out
}

func canonicalPath(basePath string, ap

i provider.API, targetModel string) string {
	switch api {
	case provider.Chat:
		return joinURLPath(basePath, "/chat/completions")
	case provider.Responses:
		return joinURLPath(basePath, "/responses")
	case provider.Anthropic:
		return anthropicPath(basePath, "/v1/messages")
	case provider.Gemini:
		return geminiPath(basePath, targetModel, false)
	default:
		return ""
	}
}

// anthropicPath avoids a duplicated /v1 segment when the base URL is already
// rooted at /v1.
func anthropicPath(basePath, suffix string) string {
	if strings.HasSuffix(basePath, "/v1") {
		return joinURLPath(basePath, strings.TrimPrefix(suffix, "/v1"))
	}
	return joinURLPath(basePath, suffix)
}

func geminiPath(baseP

ath, targetModel string, stream bool) string {
	model := strings.TrimPrefix(strings.TrimSpace(targetModel), "models/")
	action := ":generateContent"
	if stream {
		action = ":streamGenerateContent"
	}
	return joinURLPath(basePath, "/models/"+model+action)
}

func joinURLPath(basePath, suffix string) string {
	return strings.TrimSuffix(basePath, "/") + "/" + strings.TrimPrefix(suffix, "/")
}

// Package rewriter adapts engine.Engine to core/rewriter.Rewriter so gost's
// node-level body rewrites can run in-process.
package rewriter

import (
	"context"
	"encoding/json"
	"fmt"
	"strings"

	"github.com/go-gost/core/logger"
	corerewriter "github.com/go-gost/core/rewriter"
	xlogger "github.com/go-gost/x/logger"

	"github.com/go-gost/llm-gw/internal/capture"

	"github.com/ginuerzh/llm-api-converter/engine"
)

// Sink receives per-request facts observed by the engine.
type Sink interface {
	Add(sid, provider, protocol string, res engine.Result)
	AddInboundProtocol(sid, protocol string)
	AddRewriteError(sid, stage, direction, ssePhase string, eventIndex int)
}

// Options configures one

 route-scoped body rewriter.
type Options struct {
	Provider    string
	Protocol    string
	Route       string
	Node        string
	TargetModel string
	Sink        Sink
	Capture     *capture.Manager
	Logger      logger.Logger
}

// Rewriter is an in-process core/rewriter.Rewriter backed by an engine.
type Rewriter struct {
	eng  *engine.Engine
	opts Options
}

// New creates a Rewriter.
func New(eng *engine.Engine, opts Options) *Rewriter {
	if opts.Logger == nil {
		opts.Logger = xlogger.Nop()
	}
	return &Rewriter{eng: eng, opts: opts}
}

// Rewrite implements core/rewriter.Rewriter.
func (r *Rewriter) Rewrite(ctx context.Context, b []byte, opts ...corerewriter.RewriteOption) ([]byte, error

) {
	var ro corerewriter.RewriteOptions
	for _, opt := range opts {
		opt(&ro)
	}

	md, _ := ro.Metadata.(map[string]any)
	meta := engine.Meta{
		SID:        stringValue(md["sid"]),
		Direction:  stringValue(md["direction"]),
		URI:        stringValue(md["uri"]),
		SSEPhase:   stringValue(md["sse_phase"]),
		EventIndex: intValue(md["event_index"]),
	}
	inbound := inboundProtocol(meta.URI)
	if inbound != "" && r.opts.Sink != nil {
		r.opts.Sink.AddInboundProtocol(meta.SID, inbound)
	}
	if meta.Direction == "request" && r.opts.Protocol == "anthropic" && r.opts.TargetModel != "" && isCountTokensURI(meta.URI) {
		b = replaceModelField(b, r.opts.TargetModel)
	}

	res, err := r.eng.Rewrite(ctx, b,

rite %s: %v", meta.Direction, err)
		return b, err
	}
	r.captureRewrite(meta, b, res.Data, res)
	if r.opts.Sink != nil {
		r.opts.Sink.Add(meta.SID, r.opts.Provider, r.opts.Protocol, res)
	}
	return res.Data, nil
}

func (r *Rewriter) captureRewrite(meta engine.Meta, original, rewritten []byte, res engine.Result) {
	if r.opts.Capture == nil || meta.SID == "" {
		return
	}
	if strings.EqualFold(strings.TrimSpace(meta.Direction), "request") {
		model := res.ClientModel
		if model == "" {
			model = requestModel(meta.URI, original)
		}
		if _, ok := r.opts.Capture.Start(meta.SID, r.opts.Route, model); !ok {
			return
		}
		r.opts.Capture.Offer(meta.SID, "request", original, rewritten, "", 0)

return
	}
	r.opts.Capture.Offer(meta.SID, "response", original, rewritten, meta.SSEPhase, meta.EventIndex)
}

func requestModel(uri string, body []byte) string {
	var v struct {
		Model string `json:"model"`
	}
	if len(body) > 0 && json.Unmarshal(body, &v) == nil && v.Model != "" {
		return v.Model
	}
	const prefix = "/v1beta/models/"
	if i := strings.Index(uri, prefix); i >= 0 {
		rest := uri[i+len(prefix):]
		if j := strings.IndexByte(rest, ':'); j > 0 {
			return rest[:j]
		}
	}
	return ""
}

func inboundProtocol(uri string) string {
	if i := strings.IndexByte(uri, '?'); i >= 0 {
		uri = uri[:i]
	}
	switch {
	case uri == "/v1/chat/completions":
		return "openai-chat"
	case uri == "/v1/res

ponses":
		return "openai-responses"
	case uri == "/v1/messages":
		return "anthropic"
	case uri == "/v1/messages/count_tokens":
		return "anthropic"
	case strings.HasPrefix(uri, "/v1beta/models/"):
		return "gemini"
	default:
		return ""
	}
}

// isCountTokensURI reports the Anthropic token-counting path, ignoring a query
// string.
func isCountTokensURI(uri string) bool {
	if i := strings.IndexByte(uri, '?'); i >= 0 {
		uri = uri[:i]
	}
	return uri == "/v1/messages/count_tokens"
}

// replaceModelField replaces only the top-level model field. The body is
// returned unchanged when it is not JSON, has no model field, or the target
// model is empty.
func replaceModelField(body []byte, model

 string) []byte {
	if len(body) == 0 || model == "" {
		return body
	}
	var raw map[string]json.RawMessage
	if err := json.Unmarshal(body, &raw); err != nil {
		return body
	}
	if _, ok := raw["model"]; !ok {
		return body
	}
	v, err := json.Marshal(model)
	if err != nil {
		return body
	}
	raw["model"] = v
	out, err := json.Marshal(raw)
	if err != nil {
		return body
	}
	return out
}

func rewriteStage(direction, ssePhase string) string {
	if strings.EqualFold(strings.TrimSpace(direction), "request") {
		return "request_rewrite"
	}
	if strings.TrimSpace(ssePhase) != "" {
		return "stream_rewrite"
	}
	return "response_rewrite"
}

func stringValue(v any) string {
	switch t := v.(type) {
	case

 string:
		return t
	case json.Number:
		return t.String()
	case fmt.Stringer:
		return t.String()
	}
	return ""
}

func intValue(v any) int {
	switch t := v.(type) {
	case int:
		return t
	case int64:
		return int(t)
	case float64:
		return int(t)
	case json.Number:
		if n, err := t.Int64(); err == nil {
			return int(n)
		}
	}
	return 0
}
